#!/usr/bin/env python3
"""检查证据矩阵与已知反例；passed 表示记录自洽，不表示四个采用目标全部达到。"""
import hashlib,json
from pathlib import Path
R=Path(__file__).resolve().parent/'results/v5'
def read(n):return json.loads((R/(n+'-v5.json')).read_text())
checks={}
def check(n,v):checks[n]=bool(v)
a=read('coverage');check('coverage_126',len(a)==126 and all(x.get('pass') and x['epsilon']['audit']['exact'] for x in a))
a=read('boundaries');check('boundaries',a['cross_all_exdev']and a['hidden_all_denied'])
a=read('concurrent');check('external_12',len(a)==12 and all(x['external_preserved']and x['external_not_in_epsilon']for x in a))
a=read('randomized');check('random_200',len(a)==200 and all(x['pass']for x in a))
a=read('completeness');check('kernel_overflow',all(x['overflow']and x['exact']for x in a if x['case']=='kernel-overflow'));check('mmap_shadow_counterexample',any(x['case']=='persistent-mmap'and x['side']=='shadow'and not x['finish']['audit']['exact']for x in a));check('mmap_external_counterexample',any(x['case']=='persistent-mmap'and x['side']=='external'and x['real_shadow_difference']for x in a));check('alias_counterexample',any(x['case']=='external-unwatched-hardlink'and x['difference']for x in a));check('tmpfile_both',all(x['execution']['returncode']==0 and x['finish']['audit']['exact']for x in a if x['case']=='tmpfile-linkat'))
a=read('crashes');check('crashes_60',len(a)==60 and all(x['pass']for x in a))
a=read('commit-window');check('window_12',len(a)==12);check('conflict_temp_clean',all(not x['temporary_files']for x in a));check('late_check_protection',all(x['external_preserved']and x['result']['outcome']=='Conflict'for x in a if x['injection']in ['before-expected','after-ready']));check('window_counterexample',all(not x['external_preserved']and x['result']['outcome']=='Committed'for x in a if x['injection']=='after-check'))
check('downtime_counterexample',read('downtime')['external_preserved']is False)
a=read('supplement');check('supplement',all(not x.get('difference')for x in a));check('hardlink_inode',all(x['before']==x['after']==x['reverted']==x['hard']for x in a if x['case']=='hardlink-inode'));check('revert_conflict',all(x['result']['outcome']=='Conflict'and x['external_preserved']for x in a if x['case']=='revert-conflict'))
a=read('rename-links');check('rename_links_4',len(a)==4 and all(x['pass']for x in a))
a=read('index-recovery');check('incremental_index_recovery',a['added_lines']==1 and a['torn_tail_rebuilt']and not a['difference']and a['next_result']['outcome']=='Unchanged')
a=read('ledger-compat');check('B3_object_projection',a['returncode']==0 and not a['difference'])
a=read('git-discard');check('git_48',len(a)==48);check('git_undo_no_interference',all(x['head_restored']and x['status_consistent']and x['index_restored']for x in a if x['interference']=='none'));check('git_after_end_preserved',all(x['result']['outcome']=='Conflict'and x['external_index_preserved']for x in a if x['interference']=='after-end-index'));check('git_during_act_stage_counterexample',all(not x['host_staging_preserved']for x in a if x['interference']=='during-act-stage'))
a=read('git-ref-conflicts');check('git_refs_9',len(a)==9 and all(x['result']['outcome']=='Conflict'and x['external_preserved']for x in a))
a=read('git-crashes');check('git_crash_indeterminate_9',len(a)==9 and all(x['restart']['git_recovery']=='Indeterminate'for x in a))
a=read('git-minimal-only-risk');check('minimal_independent_risk',a['bytes_changed']and not a['minimal']['stdout']and bool(a['default_independent']['stdout']))
a=read('git-fixed');check('git_no_op_6',len(a)==6 and all(x['commit']['outcome']=='Unchanged'for x in a))
a=read('git-index');check('git_index_12',len(a)==12 and all(not x[k]['stdout']and x[k]['returncode']==0 for x in a for k in ['inside','host','inside_after_host']))
a=read('git-private-semantics');check('private_stage_counterexample',len(a)==2 and all(not x['staging_equal']for x in a))
a=read('git-regression');check('git_regression_48',len(a)==48 and all(x['status_expected']and x['inside']['returncode']==0 for x in a))
a=read('builds');check('builds_15',len(a)==15 and all(sum(x['mode']==m and x['returncode']==0 for x in a)==3 for m in ['none','ns','B3','S','S2']))
a=read('checkouts');check('checkouts_45',len(a)==45 and all(x['returncode']==0 and not x['status']for x in a))
a=read('micro');check('micro_30',len(a)==30 and all(x['returncode']==0 and x['observation']['failed']==0 and x['observation']['iterations']==20000 for x in a))
a=read('initial');check('initial_9',len(a)==9)
check('S_initial_9',len(read('initial-s'))==9)
a=read('fixed');check('fixed_72',len(a)==72);check('no_op_index_unchanged',all(x['index_bytes_before']==x['index_bytes_after']for x in a if x['mode']=='S2'))
a=read('settlement');check('settlement_18',len(a)==18 and all(x['outcome']=='Committed'and x['epsilon_count']==x['changed']for x in a))
a=read('renames');check('renames_30',len(a)==30 and all(x['returncode']==0 for x in a));check('single_rename',all(x['settlement']['rename_syscalls']==1 and x['settlement']['applied']==0 for x in a if x['mode']=='S2'))
a=read('incremental');check('incremental',a['act1']['returncode']==a['act3']['returncode']==a['host']['returncode']==0 and len(a['compiled3'])==1 and 'lattice-cli' in a['compiled3'][0] and not a['compiled_host'])
a=read('baseline-integrity');check('old_files_unchanged',a['checked']==2183 and not a['mismatch'])
result=dict(passed=all(checks.values()),checks=checks,adoption_targets=read('summary')['targets']);(R/'audit-v5.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(json.dumps(result,ensure_ascii=False,indent=2));raise SystemExit(0 if result['passed']else 1)
